INSERT INTO tingkatan(id,nama,urutan,parent_id) VALUES (8,'sederhana / umum',4,NULL);
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (29,1,'Tumpek Landep','Tumpek Landep merupakan hari suci pemujaan ke hadapan Ida Sang Hyang Widhi Wasa dalam manifestasi-Nya sebagai Sang Hyang Pasupati dan Bhatara Siwa untuk memohon ketajaman pikiran (landeping idep) serta menyucikan peralatan/senjata berbahan logam atau besi.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (30,1,'Tumpek Wariga / Tumpek Uduh / Tumpek Pengatag / Tumpek Bubuh','Tumpek Wariga jatuh 25 hari sebelum Hari Raya Galungan sebagai pemujaan kepada Sang Hyang Sangkara (Dewa penguasa tumbuh-tumbuhan) untuk memohon kesuburan tanaman agar berbuah, berbunga, dan berdaun lebat.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (31,1,'Tumpek Krulut','Berdasarkan Lontar Aji Gurnita dan Sundarigama, Tumpek Krulut adalah hari suci kasih sayang (lulut) dan pemujaan kepada Dewa Iswara / Asta Aiswarya yang berstana pada suara suci gamelan (tetabuhan/gong).','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (32,1,'Tumpek Uye / Tumpek Kandang','Tumpek Uye atau Tumpek Kandang adalah pemujaan ke hadapan Sang Hyang Rare Angon (manifestasi Dewa Siwa sebagai penggembala makhluk hidup) untuk mengupacarai hewan ternak dan binatang peliharaan.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (33,1,'Tumpek Wayang','Tumpek Wayang merupakan pemujaan ke hadapan Bhatara Iswara untuk menyucikan kesenian wayang dan gamelan gender, sekaligus hari ruwatan (Atma Kerthi / Sapuh Leger) bagi anak yang lahir pada Wuku Wayang agar terbebas dari pengaruh Sang Hyang Kala.','hari_raya_tetap');
INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (34,1,'Rambut Sedana','Sebagaimana ajaran Panca Yajna, upacara pemujaan Rambut Sedana dapat disesuaikan dengan kemampuan (desa, kala, patra) dan tingkatannya, yang dibagi menjadi tiga.','dewasa');
