INSERT INTO upacara(id,kategori_yadnya_id,nama,deskripsi,jenis_penentuan) VALUES (41,4,'Kecelakaan Abot','2. Yen Kacelakaan Sing Nganti Tatu, Getih Netes, utawa Pati (Kecelakaan Abot)','dewasa');
