INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2009,9,'Tingkat Nista (Sederhana): Menggunakan Canang Sari, dupa, dan Tirtha Pasupati.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2010,9,'Tingkat Madya (Menengah): Menggunakan Banten Pejati (Pras, Daksina, Ajuman, Tipat Kelanan), Tumpeng Putih Kuning lengkap dengan lauk sate berisi terasi merah dan raka-raka, serta Sesayut Pasupati dan Pareresikan.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2011,9,'Di Sanggah Kemulan / Pamerajan: Tegteg, Daksina, Pras, Ajuman, Suci, Tumpeng Putih Kuning lengkap dengan lauk sate dan raka-raka, Canang Wangi, serta Pareresik.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2012,9,'Di Perapen / Tempat Pusaka & Kendaraan: Sesayut Pasupati (tumpeng merah, raka-raka, jajan, kojong balung, kulit tebasan daun andong, berlauk ayam biying/merah), Sesayut Jayeng Perang (2 tumpeng putih berpuncak merah dan 1 tumpeng hitam berpuncak putih beralas beras triwarna), Sesayut Kusumayuda (tumpeng pancawarna mengelilingi kelapa gading), Sesayut Guru, Prayascita, Sorohan Alit, Durmanggala, Byakala, serta Segehan Agung Pasupati.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2013,9,'Di Sanggah Pamerajan, Pura Subak, atau Pelinggih Sedahan Abian: Banten Pejati (Pras, Daksina, Ajuman, Tipat Kelanan), Sesayut/Tebasan, Tulung, Tumpeng Agung, Babi Guling (atau itik), jajan, raka-raka, Penyeneng, Tatebus, dan Peras Topeng.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2014,9,'Sarana pada Pepohonan (Untuk Ngatag): Bubur sumsum dari tepung beras (bubuh) yang dioleskan pada batang pohon, Satsat/gantungan janur sebagai simbol kesucian, Canang Sari, dan Dapetan/Penyeneng.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2015,9,'Banten Pokok & Ayaban: Suci, Daksina, Pras, Ajuman/Soda, Pengambean, Pangulapan, Pangenteg, Penyeneng, dan Sesayut/Tebasan.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2016,9,'Banten Khusus Gong/Tetabuhan: Ketipat Gong, Ketipat Kelanan, Blabaran, Canang Wangi, Lenga Wangi, Pasucian, Rantasan, dan Toya Kumkuman.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2017,9,'Banten Pembersihan & Sor: Prayascita, Byakala, serta Segehan yang dilengkapi penyamblehan ayam (pitik samlunglung).','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2018,9,'Tingkat Nista (Banten Alit): Pras Penyeneng, Banten Guru, Tegen-tegenan (berisi nasi bungkus daun pisang dan buah pinang), dilengkapi Daksina (kelapa, telur, tipat, beras) dan Canang Sari.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2019,9,'Tingkat Madya (Sedang): Sesayut, Pengambean, Pengulapan, Pras Penyeneng, Jerimpen, Daksina, Canang Sari, serta nasi wakul dari daun ron lengkap dengan tangkih berisi kacang saur, telur, dan sampian latih guak.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2020,9,'Tingkat Utama (Banten Agung): Sayut Pengambean, Pras Penyeneng, Banten Guru, Sayut Pengulapan, Pucak Manik, Banten Penyegjeg, Banten Pengiring, Sayut Tebasan, Sayut Telepokan, Tegen-tegenan, dan Banten Guling.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2021,9,'Di Sanggah Pamerajan: Suci, Daksina, Pras, Ajuman, Penek, Sodan Putih Kuning, Lenga Wangi, Burat Wangi, Penyeneng, dan Pasucian.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2022,9,'Hewan Berkaki Empat (Jantan): Tumpeng, Sesayut, Penyeneng, Reresik/Pabersihan, Jerimpen, dan Canang Raka.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2023,9,'Hewan Berkaki Empat (Betina): Sama seperti hewan jantan, ditambah Ketipat Belekok, Blayag, dan Pesor.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2024,9,'Hewan Unggas: Ketipat Kedis, Ketipat Sida Purna, Ketipat Bagia, Ketipat Pandawa, Penyeneng, Tatebus, dan Kembang Payasan.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2025,9,'Tingkat Sederhana / Umum: Banten Pejati (Pras, Daksina, Ajuman, Tipat Kelanan), Dapetan, Peras Pengambean, Tebasan, Canang Meraka, Pasucian, dan Byakala.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2026,9,'Tingkat Utama (Pada Kotak/Kropak Wayang di Rangki): Suci 1 soroh lengkap dengan runtutannya, Pras, Daksina, Ajengan dengan lauk itik/bebek putih (atau bebek betutu), Sedah Wohan, Canang Meraka, Canang Pangkonan, Pasucian, Pulagembal, Sekar Taman, dan Pajegan.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2027,9,'Banten Pokok: Banten Pejati (Pras, Daksina, Ajuman, Tipat Kelanan).','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2028,9,'Sarana Pendukung: Canang sari, burat wangi, lenga wangi, serta Sesayut Pageh Tuwuh atau Sesayut Arta Sempurna.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2029,9,'Banten Pokok: Banten Pejati dan Banten Suci (seperti Suci Alit/Sari).','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2030,9,'Banten Tataban: Tumpeng Pitu (7) atau Tumpeng Selikur (21) lengkap dengan Pulagembal dan Sekar Setaman.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2031,9,'Banten Sor: Segehan Agung.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2032,9,'Banten Pokok: Banten Suci Gede/Laksana, Catur, dan Daksina Gede.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2033,9,'Banten Tataban & Ayaban: Pulagembal Bebangkit, Jerimpen agung, serta Gebogan buah dan jajan pasar dalam jumlah besar.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2034,9,'Upacara Penyucian & Pecaruan: Dilengkapi dengan upacara pembersihan (Prayascita, Byakala, Penglukatan) serta banten Caru di area sekitar tempat usaha untuk menetralisir energi negatif.','Tab Dewa Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2035,9,'Surya, Pertiwi, & Sang Pemuput: Pras, Ajuman, Daksina, Tipat Kelanan, dan Suci 2 soroh (Dewa-Dewi).','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2036,9,'Banten Caru: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Suci 2 soroh, Tumpeng Pitu, Bayuan Alit, Olahan Caru Panca Sanak (ditambah asu bang bungkem dan bebek bulu sikep) lengkap dengan nasi caru dan Nasi Wong-wongan sesuai warna serta urip (urip asu bang bungkem 33 di kelod kauh dan bebek bulu sikep 44 di kelod kangin), Byakala, Segehan Agung, Gelar Sanga, serta bale pegenian.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2037,9,'Banten Pebersihan: Durmanggala, Prayascita, dan Penglukatan lengkap dengan eteh-etehnya serta Lis Gede.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2038,9,'Surya, Pertiwi, & Sang Pemuput: Pras, Ajuman, Daksina, Tipat Kelanan, dan Banten Catur Rebah.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2039,9,'Banten Caru: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Catur Rebah, Tumpeng Pitu, Bayuan Alit, Olahan Caru Panca Kelud (ditambah kambing urip 44 di kaja dan angsa urip 55 di kangin) lengkap dengan nasi caru dan Nasi Wong-wongan sesuai warna serta urip, Byakala, Segehan Agung, Gelar Sanga, serta bale pegenian.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2040,9,'Banten Caru: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Catur Rebah, Tumpeng Pitu, Bayuan Alit, Olahan Caru Balik Sumpah (ditambah godel/anak sapi urip 99 di kelod dan kucit butuhan urip 88 di madiya/tengah) lengkap dengan nasi caru dan Nasi Wong-wongan sesuai warna serta urip, Byakala, Segehan Agung, Gelar Sanga, serta bale pegenian.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2041,9,'Surya, Pertiwi, & Sang Pemuput: Pras, Ajuman, Daksina, Tipat Kelanan, dan Banten Catur Muka (Sanggar Surya merong tiga).','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2042,9,'Banten Caru: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Catur Muka, Tumpeng Pitu, Bayuan Alit, Olahan Caru Labuh Gentuh (ditambah kidang urip 55 di kangin, menjangan urip 77 di kauh, ayam ijo alab urip 21 di kaja kauh, sapi urip 77 di kauh, dan kambing urip 88 di kaja) lengkap dengan nasi caru dan Nasi Wong-wongan, Byakala, Segehan Agung, dan Gelar Sanga.','Tab Bhuta Yadnya');
INSERT INTO kutipan(id,sumber_id,teks,halaman) VALUES (2043,9,'Banten Caru: Pras, Daksina, Sodan/Rayunan/Ajuman, Tipat Kelanan, Catur Muka, Tumpeng Pitu, Bayuan Alit, Olahan Caru Masasah Agung (menggunakan 3 ekor kerbau di kaja, madiya, dan kelod sesuai urip), Nasi Wong-wongan, Byakala, Segehan Agung, dan Gelar Sanga.','Tab Bhuta Yadnya');
